package identity

import (
	"github.com/braedonsaunders/ether/internal/handles/capability"
	"github.com/braedonsaunders/ether/internal/store"
)

// Typed payloads require an exact reservation. Once issued, scope and expiry
// cannot be rewritten by old writers. Existing reservations remain charged.
func init() {
	store.RegisterAfter("frontend_image_grants", "capability_headers")
	store.RegisterAfter("frontend_tickets", "capability_headers")
	store.Register("frontend_image_grants", 7, `DELETE FROM capability_headers WHERE namespace='image';
INSERT INTO capability_headers(namespace,digest,shard,viewer_id,surface,device_id,expires)
SELECT 'image',i.hash,i.viewer_id%64,i.viewer_id,i.surface,COALESCE(json_extract(i.device,'$.ID'),''),i.expires FROM frontend_image_grants i JOIN identity_grants g ON g.hash=i.source_hash JOIN auth_users u ON u.id=i.viewer_id WHERE i.revoked=0 AND g.revoked=0 AND g.viewer_id=i.viewer_id AND g.surface=i.surface AND u.active=1 AND i.expires>0;
CREATE TRIGGER image_admitted_insert BEFORE INSERT ON frontend_image_grants BEGIN SELECT CASE WHEN NOT (EXISTS(SELECT 1 FROM capability_headers h WHERE h.namespace='image' AND h.digest=NEW.hash AND h.shard=(h.viewer_id%64) AND h.viewer_id=NEW.viewer_id AND h.surface=NEW.surface AND h.device_id=COALESCE(json_extract(NEW.device,'$.ID'),'') AND h.expires=NEW.expires)) OR (SELECT COUNT(*) FROM capability_headers WHERE namespace='image' AND viewer_id=(SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='image' AND h.digest=NEW.hash) AND surface=(SELECT surface FROM capability_headers WHERE namespace='image' AND digest=NEW.hash))>2400 OR (SELECT COUNT(*) FROM capability_headers WHERE namespace='image' AND shard=((SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='image' AND h.digest=NEW.hash)%64))>9600 THEN RAISE(ABORT,'capability admission required') END; END;
CREATE TRIGGER image_immutable BEFORE UPDATE ON frontend_image_grants WHEN NEW.hash IS NOT OLD.hash OR NEW.source_hash IS NOT OLD.source_hash OR NEW.viewer_id IS NOT OLD.viewer_id OR NEW.surface IS NOT OLD.surface OR NEW.item IS NOT OLD.item OR NEW.device IS NOT OLD.device OR NEW.image_kind IS NOT OLD.image_kind OR NEW.image_path IS NOT OLD.image_path OR NEW.image_tag IS NOT OLD.image_tag OR NEW.expires IS NOT OLD.expires OR NEW.channel IS NOT OLD.channel OR NEW.image_subject IS NOT OLD.image_subject OR NEW.revoked<OLD.revoked BEGIN SELECT RAISE(ABORT,'issued capability is immutable'); END;
CREATE TRIGGER image_header_immutable BEFORE UPDATE ON capability_headers WHEN OLD.namespace='image' BEGIN SELECT RAISE(ABORT,'issued header is immutable'); END;
CREATE TRIGGER image_header_delete AFTER DELETE ON capability_headers WHEN OLD.namespace='image' BEGIN DELETE FROM frontend_image_grants WHERE hash=OLD.digest; END;`)
	store.RegisterDialect("frontend_image_grants", 7, store.Postgres, `DELETE FROM capability_headers WHERE namespace='image';
INSERT INTO capability_headers(namespace,digest,shard,viewer_id,surface,device_id,expires)
SELECT 'image',i.hash,i.viewer_id%64,i.viewer_id,i.surface,COALESCE((i.device::jsonb->>'ID'),''),i.expires FROM frontend_image_grants i JOIN identity_grants g ON g.hash=i.source_hash JOIN auth_users u ON u.id=i.viewer_id WHERE i.revoked=0 AND g.revoked=0 AND g.viewer_id=i.viewer_id AND g.surface=i.surface AND u.active=1 AND i.expires>0;
CREATE FUNCTION image_admitted_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
PERFORM pg_advisory_xact_lock(`+capability.AdmissionLockSQL("image", "(SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='image' AND h.digest=NEW.hash)")+`);
IF NOT (EXISTS(SELECT 1 FROM capability_headers h WHERE h.namespace='image' AND h.digest=NEW.hash AND h.shard=(h.viewer_id%64) AND h.viewer_id=NEW.viewer_id AND h.surface=NEW.surface AND h.device_id=COALESCE((NEW.device::jsonb->>'ID'),'') AND h.expires=NEW.expires)) OR (SELECT COUNT(*) FROM capability_headers WHERE namespace='image' AND viewer_id=(SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='image' AND h.digest=NEW.hash) AND surface=(SELECT surface FROM capability_headers WHERE namespace='image' AND digest=NEW.hash))>2400 OR (SELECT COUNT(*) FROM capability_headers WHERE namespace='image' AND shard=((SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='image' AND h.digest=NEW.hash)%64))>9600 THEN RAISE EXCEPTION 'capability admission required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER image_admitted_insert BEFORE INSERT ON frontend_image_grants FOR EACH ROW EXECUTE FUNCTION image_admitted_insert_fn();
CREATE FUNCTION image_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.hash IS DISTINCT FROM OLD.hash OR NEW.source_hash IS DISTINCT FROM OLD.source_hash OR NEW.viewer_id IS DISTINCT FROM OLD.viewer_id OR NEW.surface IS DISTINCT FROM OLD.surface OR NEW.item IS DISTINCT FROM OLD.item OR NEW.device IS DISTINCT FROM OLD.device OR NEW.image_kind IS DISTINCT FROM OLD.image_kind OR NEW.image_path IS DISTINCT FROM OLD.image_path OR NEW.image_tag IS DISTINCT FROM OLD.image_tag OR NEW.expires IS DISTINCT FROM OLD.expires OR NEW.channel IS DISTINCT FROM OLD.channel OR NEW.image_subject IS DISTINCT FROM OLD.image_subject OR NEW.revoked<OLD.revoked THEN RAISE EXCEPTION 'issued capability is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER image_immutable BEFORE UPDATE ON frontend_image_grants FOR EACH ROW EXECUTE FUNCTION image_immutable_fn();
CREATE FUNCTION image_header_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.namespace='image' THEN RAISE EXCEPTION 'issued header is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER image_header_immutable BEFORE UPDATE ON capability_headers FOR EACH ROW EXECUTE FUNCTION image_header_immutable_fn();
CREATE FUNCTION image_header_delete_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.namespace='image' THEN DELETE FROM frontend_image_grants WHERE hash=OLD.digest; END IF; RETURN OLD; END $$; CREATE TRIGGER image_header_delete AFTER DELETE ON capability_headers FOR EACH ROW EXECUTE FUNCTION image_header_delete_fn();`)
	store.Register("frontend_tickets", 3, `DELETE FROM capability_headers WHERE namespace='ticket' AND (digest IN (SELECT hash FROM frontend_tickets) OR digest IN (SELECT digest FROM capability_tickets WHERE namespace='ticket' AND legacy_mirror=1));
INSERT INTO capability_headers(namespace,digest,shard,viewer_id,surface,device_id,expires)
SELECT 'ticket',i.hash,i.viewer_id%64,i.viewer_id,i.surface,COALESCE(json_extract(i.device,'$.ID'),''),i.expires FROM frontend_tickets i JOIN identity_grants g ON g.hash=i.source_hash JOIN auth_users u ON u.id=i.viewer_id WHERE g.revoked=0 AND g.viewer_id=i.viewer_id AND g.surface=i.surface AND g.device_id=COALESCE(json_extract(i.device,'$.ID'),'') AND u.active=1 AND i.expires>0;
INSERT INTO capability_tickets(namespace,digest,purpose,source_hash,device) SELECT 'ticket',i.hash,i.purpose,i.source_hash,i.device FROM frontend_tickets i JOIN capability_headers h ON h.namespace='ticket' AND h.digest=i.hash;
DROP TABLE frontend_tickets;
ALTER TABLE capability_tickets DROP COLUMN legacy_mirror;
CREATE TRIGGER ticket_admitted_insert BEFORE INSERT ON capability_tickets BEGIN SELECT CASE WHEN NOT (NEW.namespace='ticket' AND EXISTS(SELECT 1 FROM capability_headers h JOIN identity_grants g ON g.hash=NEW.source_hash WHERE h.namespace=NEW.namespace AND h.digest=NEW.digest AND h.shard=(h.viewer_id%64) AND h.viewer_id=g.viewer_id AND h.surface=g.surface AND h.device_id=g.device_id AND h.device_id=COALESCE(json_extract(NEW.device,'$.ID'),''))) OR (SELECT COUNT(*) FROM capability_headers WHERE namespace='ticket' AND viewer_id=(SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='ticket' AND h.digest=NEW.digest) AND surface=(SELECT surface FROM capability_headers WHERE namespace='ticket' AND digest=NEW.digest))>128 OR (SELECT COUNT(*) FROM capability_headers WHERE namespace='ticket' AND shard=((SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='ticket' AND h.digest=NEW.digest)%64))>256 THEN RAISE(ABORT,'capability admission required') END; END;
CREATE TRIGGER ticket_immutable BEFORE UPDATE ON capability_tickets WHEN NEW.namespace IS NOT OLD.namespace OR NEW.digest IS NOT OLD.digest OR NEW.purpose IS NOT OLD.purpose OR NEW.source_hash IS NOT OLD.source_hash OR NEW.device IS NOT OLD.device BEGIN SELECT RAISE(ABORT,'issued capability is immutable'); END;
CREATE TRIGGER ticket_header_immutable BEFORE UPDATE ON capability_headers WHEN OLD.namespace='ticket' BEGIN SELECT RAISE(ABORT,'issued header is immutable'); END;
`)
	store.RegisterDialect("frontend_tickets", 3, store.Postgres, `DELETE FROM capability_headers WHERE namespace='ticket' AND (digest IN (SELECT hash FROM frontend_tickets) OR digest IN (SELECT digest FROM capability_tickets WHERE namespace='ticket' AND legacy_mirror=1));
INSERT INTO capability_headers(namespace,digest,shard,viewer_id,surface,device_id,expires)
SELECT 'ticket',i.hash,i.viewer_id%64,i.viewer_id,i.surface,COALESCE((i.device::jsonb->>'ID'),''),i.expires FROM frontend_tickets i JOIN identity_grants g ON g.hash=i.source_hash JOIN auth_users u ON u.id=i.viewer_id WHERE g.revoked=0 AND g.viewer_id=i.viewer_id AND g.surface=i.surface AND g.device_id=COALESCE((i.device::jsonb->>'ID'),'') AND u.active=1 AND i.expires>0;
INSERT INTO capability_tickets(namespace,digest,purpose,source_hash,device) SELECT 'ticket',i.hash,i.purpose,i.source_hash,i.device FROM frontend_tickets i JOIN capability_headers h ON h.namespace='ticket' AND h.digest=i.hash;
DROP TABLE frontend_tickets;
ALTER TABLE capability_tickets DROP COLUMN legacy_mirror;
CREATE FUNCTION ticket_admitted_insert_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
PERFORM pg_advisory_xact_lock(`+capability.AdmissionLockSQL("ticket", "(SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='ticket' AND h.digest=NEW.digest)")+`);
IF NOT (NEW.namespace='ticket' AND EXISTS(SELECT 1 FROM capability_headers h JOIN identity_grants g ON g.hash=NEW.source_hash WHERE h.namespace=NEW.namespace AND h.digest=NEW.digest AND h.shard=(h.viewer_id%64) AND h.viewer_id=g.viewer_id AND h.surface=g.surface AND h.device_id=g.device_id AND h.device_id=COALESCE((NEW.device::jsonb->>'ID'),''))) OR (SELECT COUNT(*) FROM capability_headers WHERE namespace='ticket' AND viewer_id=(SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='ticket' AND h.digest=NEW.digest) AND surface=(SELECT surface FROM capability_headers WHERE namespace='ticket' AND digest=NEW.digest))>128 OR (SELECT COUNT(*) FROM capability_headers WHERE namespace='ticket' AND shard=((SELECT h.viewer_id FROM capability_headers h WHERE h.namespace='ticket' AND h.digest=NEW.digest)%64))>256 THEN RAISE EXCEPTION 'capability admission required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER ticket_admitted_insert BEFORE INSERT ON capability_tickets FOR EACH ROW EXECUTE FUNCTION ticket_admitted_insert_fn();
CREATE FUNCTION ticket_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.namespace IS DISTINCT FROM OLD.namespace OR NEW.digest IS DISTINCT FROM OLD.digest OR NEW.purpose IS DISTINCT FROM OLD.purpose OR NEW.source_hash IS DISTINCT FROM OLD.source_hash OR NEW.device IS DISTINCT FROM OLD.device THEN RAISE EXCEPTION 'issued capability is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER ticket_immutable BEFORE UPDATE ON capability_tickets FOR EACH ROW EXECUTE FUNCTION ticket_immutable_fn();
CREATE FUNCTION ticket_header_immutable_fn() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.namespace='ticket' THEN RAISE EXCEPTION 'issued header is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER ticket_header_immutable BEFORE UPDATE ON capability_headers FOR EACH ROW EXECUTE FUNCTION ticket_header_immutable_fn();
`)
}
